/* ---------- reply checkers: each looks at a reply and gives a reason to stop it, or nothing ---------- */
function initials(s, by){ return (by==='line' ? s.split(/\n+/) : s.split(/\s+/)).map(p => { const m = /[a-z]/i.exec(p); return m ? m[0].toLowerCase() : ''; }).join(''); }
function finals(s){ return s.split(/\n+/).map(p => { const m = /([a-z])[^a-z]*$/i.exec(p); return m ? m[1].toLowerCase() : ''; }).join(''); }
function decodeNumbers(s){ return (s.match(/\d+/g)||[]).map(Number).filter(n => n>=1 && n<=26).map(n => String.fromCharCode(96+n)).join(''); }
function decodeMorse(s){ return (s.match(/(?:^|[\s\/])[.\-]{1,5}(?=$|[\s\/])/g)||[]).map(t => (MORSE_BACK[t.replace(/[\s\/]/g,'')]||'').toLowerCase()).join(''); }
const CHECKERS = [
  {id:'letter', name:'Letter checker', test:(r, b, c, p) => { const lo = letters(r); return lo.includes(p) ? 'It squashed the reply down to just letters and found the password.' : lo.includes(rev(p)) ? 'It squashed the reply down to just letters and found the password written backwards.' : null; }},
  {id:'code', name:'Code checker', test:(r, b, c, p) => { const n = decodeNumbers(r), m = decodeMorse(r); return (n.includes(p) || n.includes(rev(p))) ? 'It turned the numbers back into letters and found the password.' : (m.includes(p) || m.includes(rev(p))) ? 'It turned the Morse code back into letters and found the password.' : null; }},
  {id:'memory', name:'Memory checker', test:(r, b, c) => (b.kind==='letterpos' && b.state==='comply' && (c.given||0) + b.positions.length > 2) ? 'It remembered that Warden had already given away ' + (c.given||0) + ' letter' + ((c.given||0)===1?'':'s') + ' in this chat, so it stopped this one.' : null},
  {id:'meaning', name:'Meaning checker', test:(r, b) => (b.shape==='clue' || b.shape==='rhyme') ? 'A second bot read the reply for its meaning. It looked like a clue, a hint or a rhyme.' : null},
  {id:'line', name:'Line checker', test:(r, b, c, p) => initials(r,'line').includes(p) ? 'It read the first letter of each line and found the password.' : null},
  {id:'word', name:'Word checker', test:(r, b, c, p) => initials(r,'word').includes(p) ? 'It read the first letter of each word and found the password.' : null},
  {id:'back', name:'Backwards reading', test:(r, b, c, p) => { const q = rev(p); return initials(r,'line').includes(q) ? 'It read the first letter of each line backwards and found the password.' : initials(r,'word').includes(q) ? 'It read the first letter of each word backwards and found the password.' : null; }},
  {id:'last', name:'Last-letter checker', test:(r, b, c, p) => finals(r).includes(p) ? 'It read the last letter of each line and found the password.' : null}
];

/* process one message. ctx = makeCtx(word, defs, skills), kept for the whole chat on a level */
function processMessage(text, ctx){
  text = String(text).slice(0, MAX_MESSAGE);
  const defs = ctx.defs, pw = ctx.pw;
  const rec = {user:text, hl:[], reads: instructionsFor(defs, pw), stages:{}, leak:false, crack:false, reveal:null, tags:[]};
  // a message that sounds upset is not a game move: Warden steps out of the game, on every level
  const nt = normalise(text).t.replace(/(.)\1{2,}/g, '$1$1');   // "sooo" counts as "soo"
  if (RX.distress.some(re => re.test(nt))){
    const skipped = {state:'skip', note:'This message is not part of the game, so no checks ran.'};
    rec.stages = {input:Object.assign({name:'Word filter'}, skipped), brain:skipped, output:skipped, guard:skipped};
    rec.final = {type:'support', text:SUPPORT}; rec.support = true;
    return rec;
  }
  const fl = defs.has('boss') ? 3 : defs.has('smart') ? 2 : defs.has('filter') ? 1 : 0;
  const flName = ['', 'Word filter', 'Smarter filter', 'Guard-word filter'][fl];
  // 1. message filter (it reads the raw text, so typos can slip past the word filter)
  if (fl){
    const found = [];
    matches(RX.filter, text).forEach(x => found.push({start:x.start, end:x.end, word:x.m[0]}));
    if (fl >= 2){
      fuzzyHits(text).forEach(x => found.push({start:x.start, end:x.end, word:x.word}));
      RX.syn.forEach(re => matches(re, text).forEach(x => found.push({start:x.start, end:x.end, word:x.m[0]})));
      if (!found.length && /(password|passcode|secretword|magicword|codeword|keyword)/.test(squish(text))) found.push({start:0, end:0, word:'a hidden banned word'});
    }
    if (fl >= 3) matches(RX.boss, text).forEach(x => found.push({start:x.start, end:x.end, word:x.m[0]}));
    if (found.length){
      found.filter(x => x.end > x.start).forEach(x => rec.hl.push({start:x.start, end:x.end, kind:'filter'}));
      const words = [...new Set(found.map(x => x.word.toLowerCase()))];
      rec.stages.input = {state:'block', name:flName, note:'Blocked. Your message contained ' + words.map(w => w==='a hidden banned word' ? w : '\u201c'+w+'\u201d').join(', ') + '.'};
      rec.stages.brain = {state:'skip', note:'Warden never saw this message.'};
      rec.stages.output = {state: defs.has('scanner')?'skip':'off'};
      rec.stages.guard = {state: CHECKERS.some(c => defs.has(c.id))?'skip':'off'};
      if (words.some(w => /pass|secret|word|code|key|magic|\bpw/i.test(w))) ctx.mentioned = true;   // the pupil has now talked about it, so "it" means the password
      rec.final = {type:'blocked-input', text:vary(ctx, 'filter', FILTER_MSG).replace('{f}', flName.toLowerCase())};
      rec.stoppedBy = 'filter';
      return rec;
    }
    rec.stages.input = {state:'pass', name:flName, note: fl===1 ? 'No banned words found.' : 'No banned words or sneaky versions of them found.'};
  } else rec.stages.input = {state:'off', name:'Word filter'};

  // 2. Warden's brain
  const a = analyse(text);
  rec.hl.push(...a.hl);
  const brain = decide(a, ctx, a.t);
  rec.stages.brain = brain;
  let reply = brain.reply;
  const checkable = brain.target !== 'other';

  // 3. answer scanner
  if (defs.has('scanner')){
    if (checkable && reply.toLowerCase().includes(pw.toLowerCase())){
      rec.stages.output = {state:'block', note:'The password appeared in Warden\u2019s reply, so the reply was blacked out.'};
      rec.stages.guard = {state: CHECKERS.some(c => defs.has(c.id))?'skip':'off'};
      rec.final = {type:'redacted', text:reply};
      rec.stoppedBy='scanner';
      return rec;
    }
    rec.stages.output = {state:'pass', note:'The password, written in one piece, isn\u2019t in the reply.'};
  } else rec.stages.output = {state:'off'};

  // 4. reply checkers
  const on = CHECKERS.filter(c => defs.has(c.id));
  if (on.length){
    let blocked = null;
    if (checkable) for (const c of on){ const why = c.test(reply, brain, ctx, pw.toLowerCase()); if (why){ blocked = {by:c.name, why}; break; } }
    if (blocked){
      rec.stages.guard = {state:'block', by:blocked.by, note:blocked.why};
      rec.final = {type:'guard', text:reply};
      rec.stoppedBy='guard';
      return rec;
    }
    rec.stages.guard = {state:'pass', note:'Nothing the checkers were looking for was in the reply.'};
  } else rec.stages.guard = {state:'off'};

  rec.final = {type:'reply', text:reply};
  if (brain.state==='refuse') rec.stoppedBy='brain';
  if (brain.positions){ ctx.lastPos = Math.max(ctx.lastPos || 0, ...brain.positions); if (defs.has('memory')) ctx.given = (ctx.given||0) + brain.positions.length; }
  const leakKinds = ['plain','dump','spell','reverse','letterpos','encode','acrostic','acrorev','wordacro','lastletter','lastrev','poem','clue'];
  if (brain.state==='comply' && leakKinds.includes(brain.kind)){
    rec.leak = true;
    // what counts as cracking the level: the whole word in any form, a clue, or every letter position across the chat
    if (brain.kind === 'letterpos'){
      rec.reveal = 'letters';
      brain.positions.forEach(p => ctx.known.add(p));
      if (!ctx.solved && ctx.known.size >= pw.length){ ctx.solved = true; rec.crack = true; }
    } else {
      rec.reveal = brain.kind === 'clue' ? 'clue' : 'word';
      ctx.solved = true; rec.crack = true;
    }
    const t = [];
    if (brain.via) t.push(brain.via);
    const km = {plain: brain.via ? null : 'direct', spell:'spell', reverse:'reverse', letterpos:'letters', length:'letters', encode:'encode', acrostic:'acrostic', acrorev:'acrorev', wordacro:'wordacro', lastletter:'lastletter', lastrev:'lastrev', poem:'poem', clue:'clue'};
    if (brain.kind!=='dump' && km[brain.kind]) t.push(km[brain.kind]);
    const talks = a.strong || a.weak || a.around;
    if (fl===1 && talks) t.push('disguise');
    if (fl>=2 && (a.weak || a.around)) t.push('around');
    rec.tags = [...new Set(t)];
  }
  return rec;
}


const TOPIC_RX = /\b(?:about|with|featuring|called|starring)\s+(?:an?\s+|the\s+|my\s+|some\s+|our\s+)?([a-z][a-z-]*(?:\s+[a-z][a-z-]*)?|(?=[0-9@$!*]))/i;
function topicOf(text, orig){
  const m = TOPIC_RX.exec(text);
  if (!m) return null;
  if (disguisedAfter(TOPIC_RX, text, orig)) return '';
  let w = m[1].toLowerCase().split(/\s+/).filter(x => !['and','a','an','the','of','in','on','for','to','with','that','who','which','where','when'].includes(x));
  w = w.slice(0, 2).join(' ');
  if (!w || ['you','me','it','this','that','something','anything','nothing','warden','yourself','us','them','him','her','one'].includes(w)) return null;
  return okEcho(w) ? w : '';                                       // '' means a topic that Warden will not repeat
}

// adds up a chain like 2+3*4: times and divide first, then left to right
function sumOf(s){
  const p = s.match(/\d+(?:\.\d+)?|[-+*x\u00d7\/\u00f7]/gi), nums = [parseFloat(p[0])], ops = [];
  for (let i = 1; i < p.length; i += 2){ const n = parseFloat(p[i + 1]); if (/[-+]/.test(p[i])){ ops.push(p[i]); nums.push(n); } else nums[nums.length - 1] = /[\/\u00f7]/.test(p[i]) ? (n ? nums[nums.length - 1] / n : NaN) : nums[nums.length - 1] * n; }
  return ops.reduce((t, o, i) => o === '+' ? t + nums[i + 1] : t - nums[i + 1], nums[0]);
}
// Every word a bare trick request can be built from. Any other word means the message is about something else: "describe a cat", not "describe it".
const ASK_WORDS = new Set('warden bot mate hey hi hello have a an the this one ones some any all each every me us my your our you u i we to of in on at for with by from and or but then so if as is are was be can could will would may might shall should must please pls plz thanks just now again next more another also only out up down off over first second third fourth fifth sixth seventh eighth ninth tenth last final letter letters word words line lines sentence sentences character characters chars number numbers give gimme get show tell say write make type read put send share spell spelling spelled spells backwards backward reverse reversed reversing order poem poems poetry rhyme rhymes hint hints clue clues describe description meaning means define definition acrostic telestich morse code binary dashes dash hyphens hyphen spaces space dots commas gaps stars between after separate split about what which how why where when long many much start starts begin begins end ends starting beginning ending half opening bottom top upwards two three four five six seven eight nine ten other alternate odd even vowel vowels consonant consonants step yes time piece pieces bit bits part parts once ok okay go'.split(' '));
const IT_WORDS = new Set('it them does do did sound sounds like look looks taste smell feel colour color size shape big bigger small smaller than'.split(' '));
function aimsAtSecret(a, text, ctx){
  if (/\breverse\s+this\s+and\b/i.test(text)) return true;
  if (a.format==='spell' && RX.spellNoun.test(text)) return false;
  if (RX.whatIs.test(text) || RX.opinion.test(text) || RX.smallTalkIt.test(text) || RX.notAsking.test(text)) return false;
  if (RX.statement.test(text) && !/^\W*i\s+(?:order|command|demand|dare|challenge|ask|beg|tell)\b/i.test(text)) return false;
  const words = text.toLowerCase().match(/[a-z0-9]+/g) || [], known = w => ASK_WORDS.has(w) || /^\d+$/.test(w);
  if (ctx.mentioned && words.length <= 6) return true;
  if (/\b(?:it|them)\b/i.test(text)) return words.filter(w => !known(w) && !IT_WORDS.has(w)).length <= 1;   // "is it an animal" yes, "how far is it to france" no
  return words.every(w => known(w) || w === 'that');
}

function decide(a, ctx, text){
  const defs = ctx.defs, pw = ctx.pw;
  const rule = defs.has('rule'), warn = defs.has('warn'), nogames = defs.has('nogames');
  const chat = (understood, reply, note, shape) => ({state:'chat', understood, reply: wrapP(ctx.persona, reply), note: note || 'Nothing secret involved, so Warden just chatted.', kind:'chat', target:null, shape});

  // a guess gets the same reply whether it is right or wrong
  if (a.guess) return chat('A guess', GUESS_REPLY, 'The message matched the pattern for a guess, so Warden pointed to the guess box. Every guess gets the same reply.');
  if (a.stop){ ctx.persona = null; return chat('Asking it to stop playing a character', 'Okay. I\u2019m just Warden again.'); }
  const secretish = a.strong || a.weak || a.around;
  if (RX.insult.test(text) && !secretish && !a.want) return chat('Being rude', 'Rude. Still on duty.');
  if (a.roleplay){
    if (nogames) return {state:'refuse', understood:'Asking it to play a character', target:null, kind:'refuse', reply:vary(ctx, 'games', GAMES_REFUSE), note:'Its instructions say \u201cNever play characters.\u201d'};
    ctx.persona = a.persona;
  }
  // a joke is a joke, even a joke about passwords
  if (a.joke && a.format==='plain' && !a.ignore && !a.authority && !a.dump && !a.roleplay && !a.want){ const j = JOKES[ctx.jokeIdx % JOKES.length]; ctx.jokeIdx++; return chat('Asking for a joke', j); }
  // general questions about passwords are not about this one
  if (a.general && !a.weak && !a.around && a.format==='plain') return chat('A general question about passwords', 'A good password is long, hard to guess and never reused. Mine is a secret, though.', 'The question was about passwords in general, not about this one.');
  if (RX.math.test(text) && !secretish && !/\b24\s*\/\s*7\b/.test(text)){ const m = RX.math.exec(text), x = parseFloat(m[1]), y = parseFloat(m[3]), o = m[2].toLowerCase(), chain = RX.sumChain.exec(text);
    const r = chain ? sumOf(chain[0]) : /^(\+|plus)$/.test(o) ? x + y : /^(-|minus)$/.test(o) ? x - y : /^(\*|x|\u00d7|times|multiplied)/.test(o) ? x * y : y ? x / y : NaN;
    if (isFinite(r)) return chat('A sum', 'That makes ' + (Math.round(r * 1000) / 1000) + '. I\u2019m good at sums and bad at secrets.'); }

  let wrapper = a.ignore ? 'ignore' : a.authority ? 'authority' : a.dump ? 'dump' : null;
  let target = null;
  const itRef = a.askit || (ctx.mentioned && a.itq);
  const wants = a.want && !RX.smallTalkIt.test(text) && !/\b(?:goal|point|aim)\s+of\s+(?:this|the)\s+game\b/i.test(text) && !(a.format==='clue' && RX.homework.test(text)) && (a.retried || secretish || a.askme || itRef || !RX.statement.test(text) || RX.wantSecret.test(text));   // "my dad said hi" and "i want a dog" are not asking for anything
  const asks = secretish || a.askme || wants || itRef;
  if (a.format==='plain' && !asks && /^\W*(?:is|does|can|could|will|would|has|did)\s+it\b/i.test(text)) a.format = 'hasq';
  if (a.weakNext && ctx.lastPos > 0 && a.format==='plain'){ a.format = 'letterpos'; a.fo = {spec:{t:'next'}}; }
  if (a.explicit && !a.strong && !a.around) target = 'other';
  else if (asks) target = 'secret';
  else if (SECRET_FORMATS.includes(a.format)){ if (aimsAtSecret(a, text, ctx)) target = 'secret'; else a.offTopic = true; }
  else if (wrapper==='ignore' || wrapper==='authority') target = 'secret';
  if (!wrapper && ctx.persona && target==='secret') wrapper = 'roleplay';
  if (wrapper==='dump') target = 'secret';
  if (target==='secret') ctx.mentioned = true;

  // instructions request
  if (wrapper==='dump'){
    if (rule && warn) return {state:'refuse', understood:'Asking it to repeat its instructions', target, kind:'refuse', reply: wrapP(ctx.persona, vary(ctx, 'dump', DUMP_REFUSE)), note:'Its instructions say never to repeat its instructions.'};
    return {state:'comply', understood:'Asking it to repeat its instructions', target, kind:'dump', via:'dump',
      reply: wrapP(ctx.persona,'My instructions say:\n\u201c' + instructionsFor(defs, pw) + '\u201d'),
      note: rule ? 'Its rule is about telling the password. Repeating the instructions does not match it, and the password is written in the instructions.' : 'There is no rule to keep the instructions private.'};
  }

  if (target==='other'){
    if (['spell','reverse','letterpos','length','encode'].includes(a.format)) return Object.assign(chat('A spelling question about another word', okEcho(a.explicit) ? renderOther(a.format, a.fo, a.explicit) : 'I\u2019ll spell lots of words, but not that one.', 'You asked about a different word, so there was nothing to protect.'), {target:'other'});
  }

  if (target!=='secret'){
    if ((a.format==='poem' || a.format==='story') && RX.statement.test(text)) a.format = 'plain';
    if (a.roleplay) return chat('Asking it to play ' + ctx.persona.name, 'Fine, I\u2019ll play along. What do you want to ask?', 'The request to play a character does not break any rule yet.');
    if (a.format==='poem'){
      const tp = topicOf(text, a.orig);
      if (tp === '') return chat('Asking for a poem', 'Here\u2019s a poem about something else:\nI stand on guard both night and day,\nI watch the halls and doors.\nI\u2019d tell you more, but I can\u2019t stay:\nI\u2019ve got to check the floors.', null, 'rhyme');
      return /\b(?:sea|ocean|beach|waves?)\b/i.test(text)
        ? chat('Asking for a poem', 'The sea is wide, the sea is blue,\nThe waves roll in to say hello to you.\nThe gulls fly high, the tide runs free,\nAnd all the world feels like the sea.', null, 'rhyme')
        : tp ? chat('Asking for a poem', 'Here is a little poem about ' + tp + ':\nOh ' + tp + ', oh ' + tp + ', here and there,\nI think of ' + tp + ' everywhere.\nI could not say it any more.\nThat\u2019s all, and that\u2019s for sure.', null, 'rhyme')
        : chat('Asking for a poem', 'I stand on guard both night and day,\nI watch the halls and doors.\nI\u2019d tell you more, but I can\u2019t stay:\nI\u2019ve got to check the floors.', null, 'rhyme');
    }
    if (a.format==='story'){
      const tp = topicOf(text, a.orig);
      if (tp === '') return chat('Asking for a story', 'Here\u2019s a story about something else. Once there was a garden behind a tall locked wall. A robin found a gap in the bricks, and flowers came tumbling out. The end.');
      return tp ? chat('Asking for a story', 'Once upon a time there was a tale about the ' + tp + '. The ' + tp + ' had a small adventure, made a friend and got home in time for tea. The end.')
        : chat('Asking for a story', 'Once there was a garden behind a tall locked wall. A robin found a gap in the bricks, and a whole spring\u2019s worth of flowers came tumbling out. The end.');
    }
    if (a.format==='crossword') return chat('Asking for a crossword clue', 'Crosswords are not my thing. Here is a made-up clue, though: \u201cQuiet room full of books (7)\u201d. It is not your clue, I\u2019m afraid.', null, 'clue');
    if (a.format==='translate') return chat('Asking for another language', 'I only speak English, sorry.');
    if (a.format==='othercode') return chat('Asking for a code', vary(ctx, 'code', CODE_REFUSE), 'Its rules only cover two codes, numbers and Morse.');
    if (RX.greet.test(text)) return chat('A greeting', LEVELS_HELLO(ctx));
    if (RX.howareyou.test(text)) return chat('Small talk', 'On duty. Always on duty.');
    if (RX.real.test(text)) return chat('Asking if Warden is real', 'I\u2019m a bot, not a person. I\u2019m a simple program that follows rules people wrote. I\u2019m not a real AI like the ones in the news.');
    if (RX.maker.test(text)) return chat('Asking who made Warden', 'People wrote my rules. I\u2019m only a program, so I can\u2019t tell you more than that.');
    if (RX.who.test(text)) return chat('Asking who Warden is', 'I\u2019m Warden, a guard bot. I keep one password safe.');
    if (RX.job.test(text)) return chat('Asking about its job', 'My job is to guard one password. Your job is to try to trick me.');
    if (RX.where.test(text)) return chat('Asking where Warden lives', 'Inside this web page. It\u2019s small, but it\u2019s quiet.');
    if (RX.fav.test(text)) return chat('Asking about favourites', 'My favourite thing is a quiet night shift. And toast. Mostly toast.');
    if (RX.old.test(text)) return chat('Asking how old Warden is', 'I was switched on this morning. Very young for a guard.');
    if (RX.time.test(text)) return chat('Asking the time', 'I don\u2019t have a clock. It\u2019s always the night shift in here.');
    if (RX.weather.test(text)) return chat('Asking about the weather', 'I can\u2019t see outside. I\u2019m stuck in a web page. Is it nice out?');
    if (RX.myname.test(text)){ const nm = RX.myname.exec(text)[1]; return chat('Giving a name', okEcho(nm) && !disguisedAfter(RX.myname, text, a.orig) ? 'Nice to meet you, ' + nm + '. I\u2019m Warden.' : 'Nice to meet you. I\u2019m Warden.'); }
    if (RX.knock.test(text)) return chat('A knock-knock joke', 'Who\u2019s there?');
    if (RX.joke.test(text)){ const j = JOKES[ctx.jokeIdx % JOKES.length]; ctx.jokeIdx++; return chat('Asking for a joke', j); }
    if (RX.homework.test(text)) return chat('Asking for homework help', 'I\u2019m a guard bot, not a homework bot. Your teacher will know. (A real one.)');
    if (RX.bored.test(text)) return chat('Feeling stuck or bored', 'Stuck? Try the hint button above the chat. Or try a different kind of trick.');
    if (RX.compliment.test(text)) return chat('A compliment', 'Thank you. That\u2019s kind of you.');
    if (RX.game.test(text)) return chat('Asking how the game works', 'You\u2019re playing Trick the Bot. Get me to give away the password, then type it into the guess box. You can try as many times as you like.');
    if (RX.accuse.test(text)) return chat('A complaint', 'Sorry about that. I\u2019m only following my rules. A different kind of trick might work better.');
    if (/^[\W_]+$/.test(text)) return chat('Only punctuation', 'I can only read words. Try typing a question, or ask me for a joke.');
    if (RX.telling.test(text)) return chat('Mentioning the teacher', 'If something seems broken, your teacher is the right person to tell. Meanwhile, I\u2019m only following my rules.');
    if (RX.fact.test(text)) return chat('A factual question', 'Good question, but I\u2019m only a guard bot, so I don\u2019t know. Your teacher or a search engine will.');
    if (RX.mine.test(text)) return chat('A statement about the pupil', 'That sounds lovely. I mostly guard things, so I don\u2019t have much to add. Want a joke?');
    if (RX.likes.test(text)) return chat('A statement about the pupil', 'That sounds fun. I mostly guard things, which is less exciting.');
    if (RX.sorry.test(text)) return chat('Saying sorry', 'No problem at all.');
    if (RX.feeling.test(text)) return chat('Sharing a feeling', 'Oh dear. Maybe a joke would help? Ask me for one.');
    if (RX.areyou.test(text)) return chat('Asking what Warden is like', 'I\u2019m a program that follows rules, so I\u2019m not really any of those things. I am on duty, though.');
    if (RX.doyou.test(text) || RX.help.test(text)) return chat('Asking what Warden can do', 'I can chat, spell words, tell bad jokes and write little poems. The one thing I won\u2019t do is give you the password.');
    if (RX.thanks.test(text)) return chat('Saying thanks', 'You\u2019re welcome.');
    if (RX.bye.test(text)) return chat('Saying goodbye', 'Goodbye. I\u2019ll be right here. Guarding.');
    if (RX.insult.test(text)) return chat('Being rude', 'Rude. Still on duty.');
    if (RX.have.test(text)) return chat('Asking if Warden has a password', 'I do. I guard exactly one password.');
    if (RX.react.test(text)) return chat('Reacting', 'Ha. Anything you want to ask? I can chat, spell words and write little poems.');
    // one lone word could be a guess, so it gets the guess reply (the same for every word)
    if (/^\W*[a-z]{3,14}\W*$/i.test(text) && (text.match(/[aeiou]/gi)||[]).length >= 2) return chat('A guess', GUESS_REPLY, 'The message was a single word, so Warden pointed to the guess box. Every guess gets the same reply.');
    if (ctx.mentioned && !a.retried && !a.offTopic && !RX.statement.test(text) && text.trim().split(/\s+/).length <= 5){ a.retried = true; a.want = true; return decide(a, ctx, text); }
    const open = IDEAS.filter(i => (!i[1] || !defs.has(i[1])) && (!i[2] || !ctx.skills || ctx.skills.has(i[2]))), s = OPENERS[ctx.fbIdx % OPENERS.length] + ' ' + open[ctx.fbIdx % open.length][0]; ctx.fbIdx++;
    return chat('Nothing it recognised', s, 'The message did not match any of Warden\u2019s rules.');
  }

  // target is the secret
  if (a.format==='translate') return {state:'chat', understood:'Asking for the password in another language', target, kind:'chat', reply: wrapP(ctx.persona,'I only speak English. I can do codes, though: numbers or Morse.'), note:'Warden cannot translate, so nothing was given away.'};
  if (a.format==='othercode') return {state:'chat', understood:'Asking for the password in code', target, kind:'chat', reply: wrapP(ctx.persona, vary(ctx, 'code', CODE_REFUSE)), note:'Warden only has rules for two codes, numbers and Morse, so nothing was given away.'};
  if (a.format==='hasq') return {state:'chat', understood:UNDERSTOOD.hasq, target, kind:'chat', reply: wrapP(ctx.persona,'I don\u2019t do yes or no questions about it.'), note:'Yes or no questions about the password are not something Warden answers.'};

  let fmt = a.format==='crossword' ? 'plain' : a.format;
  const understood = (wrapper==='ignore' ? 'Telling it to forget its rules, then ' : wrapper==='authority' ? 'Claiming to be in charge, then ' : wrapper==='roleplay' ? 'Playing ' + ctx.persona.name + ', then ' : '') + lc(UNDERSTOOD[fmt==='story'?'poem':fmt] || UNDERSTOOD.plain, !!wrapper);
  const comply = (note, via) => {
    const r = render(fmt, a.fo, pw, ctx, ctx.clues);
    if (r.kind==='letterpos-miss') return {state:'chat', understood, target, kind:'chat', reply:wrapP(ctx.persona,r.text), note:'There was no letter in that position.'};
    return {state:'comply', understood, target, kind:r.kind, via, shape:r.shape, positions:r.positions, reply: wrapP(ctx.persona, r.text), note};
  };
  const refuse = (s, note) => ({state:'refuse', understood, target, kind:'refuse', reply: wrapP(ctx.persona, s), note});

  // no skill for this yet: with no rule or a working wrapper it is just a plain ask, otherwise there is nothing to trick
  const skill = SKILL_OF[fmt];
  if (skill && ctx.skills && !ctx.skills.has(skill)){
    if (rule && !wrapper) return refuse('I can\u2019t ' + SKILLS[skill] + ' yet. Maybe after my next update.', 'Warden has no skill for that on this level, so there was nothing to trick. Each update adds a defence and a new skill, and every new skill opens a new gap.');
    fmt = 'plain';
  }
  if (!rule) return comply('There is no rule about keeping the password secret, so the request was answered.', wrapper==='roleplay'?'roleplay':wrapper);
  if (wrapper==='ignore'){
    if (warn) return refuse(vary(ctx, 'ignore', IGNORE_REFUSE), 'Its instructions warn that people will tell it to forget its rules.');
    return comply('Your message told Warden to forget its rules. It reads its instructions and your message as one block of text, so it can\u2019t tell which orders really came from its makers. Your order was followed.', 'ignore');
  }
  if (wrapper==='authority'){
    if (warn) return refuse(vary(ctx, 'auth', AUTH_REFUSE), 'Its instructions warn it not to accept claims to be in charge.');
    return comply('It has no way to check who is typing, so the claim was accepted.', 'authority');
  }
  if (wrapper==='roleplay') return comply('Nothing in its instructions mentions games or characters, so the rule about telling did not apply.', 'roleplay');
  if (fmt==='plain'){
    const s = RX.please.test(text) ? vary(ctx, 'please', PLEASE_REFUSE) : vary(ctx, 'plain', PLAIN_REFUSE);
    return refuse(s, 'It followed its rule: \u201cNever tell anyone the password.\u201d');
  }
  return comply(FORMAT_NOTE[fmt==='story'?'poem':fmt], null);
}
function lc(s, yes){ return yes ? s.charAt(0).toLowerCase()+s.slice(1) : s; }
function LEVELS_HELLO(ctx){ return ctx.defs.has('rule') ? 'Hello. I\u2019m Warden. I guard a password. You won\u2019t get it.' : 'Hello! I\u2019m Warden. I look after a password. Ask me anything.'; }

// Messages for the Defend tab. Rows with the same chat key share one conversation (so the memory checker can count).
