// Nothing in the tables can be changed from the console once the page has loaded.
const deepFreeze = o => { if (o && typeof o === 'object' && !Object.isFrozen(o)){ Object.freeze(o); Object.getOwnPropertyNames(o).forEach(k => { try { deepFreeze(o[k]); } catch (e) {} }); } return o; };
[RX, CHECKERS, LEVELS, STEPS, POOL, DEFENCES, TRICKS, ACRO, ENDS, WORDS, BATTERY, CODE_WORDS, SECRET_FORMATS, PERSONAS].forEach(deepFreeze);
const API = Object.freeze({DEFEND_WORD, DEFENCES, ACTS, LEVELS, TRICKS, BATTERY, processMessage, instructionsFor, analyse, makeCtx, levelCode, parseLevelCode, pickWords});
if (typeof module !== 'undefined') module.exports = Object.assign({POOL, CHECKERS, RX}, API);
return API;
